<script>
  import { BookOpen, Building2, BriefcaseBusiness, GraduationCap, Users, FileCheck2, ClipboardList, ChartNoAxesColumn, FileText, ShieldCheck, LayoutDashboard, ChevronLeft, ChevronRight, X, LogOut, CircleHelp } from 'lucide-svelte';
  let { modules = [], active = '', role = '', collapsed = false, mobileOpen = false, onnavigate = () => {}, ontoggle = () => {}, onlogout = () => {} } = $props();
  const icons = { PROGRAMAS:BookOpen,ESTUDIANTES:GraduationCap,EMPRESAS:Building2,TUTORES_ACADEMICOS:Users,TUTORES_EMPRESARIALES:BriefcaseBusiness,CONVENIOS:FileCheck2,PRACTICAS:BriefcaseBusiness,SEGUIMIENTOS:ClipboardList,EVALUACIONES:ChartNoAxesColumn,DOCUMENTOS:FileText,SEGURIDAD:ShieldCheck };
  function code(module){return module.modulo_codigo||module.codigo||''}
  function title(module){return module.modulo_nombre||module.nombre||module.title||'Módulo'}
</script>
{#if mobileOpen}<button class="mobile-scrim" onclick={()=>ontoggle('close')} aria-label="Cerrar navegación"></button>{/if}
<aside class="sidebar" class:collapsed class:mobile-open={mobileOpen}><div class="brand-row"><div class="brand-mark"><BriefcaseBusiness size={19}/></div>{#if !collapsed}<div class="brand-name">Prácticas<span>GESTIÓN PROFESIONAL</span></div>{/if}<button class="mobile-close icon-button" onclick={()=>ontoggle('close')} aria-label="Cerrar menú"><X size={18}/></button></div><div class="workspace-card"><div class="workspace-avatar">U</div>{#if !collapsed}<div><strong>Universidad</strong><span>Sistema de prácticas</span></div><span class="workspace-dot"></span>{/if}</div><button class="nav-dashboard" class:active={active==='dashboard'} onclick={()=>onnavigate('dashboard')}><LayoutDashboard size={18}/>{#if !collapsed}<span>Resumen general</span>{/if}</button><div class="nav-label">{#if !collapsed}GESTIÓN ACADÉMICA{/if}</div><nav class="side-nav">{#each modules as module (module.modulo_id||module.codigo||module.modulo_codigo)}{@const key=code(module)}{@const Icon=icons[key]||FileText}<button class="nav-item" class:active={active===key} title={title(module)} onclick={()=>onnavigate(key)}><Icon size={18}/>{#if !collapsed}<span>{title(module)}</span><span class="nav-dot"></span>{/if}</button>{/each}</nav><div class="sidebar-bottom">{#if !collapsed}<div class="help-card"><CircleHelp size={17}/><span>Permisos desde la base de datos</span></div>{/if}<div class="user-profile"><div class="profile-avatar">{role?.slice(0,1)||'U'}</div>{#if !collapsed}<div class="profile-copy"><strong>{role||'Usuario'}</strong><span>Acceso por rol</span></div>{/if}<button class="logout-button" onclick={onlogout} aria-label="Cerrar sesión" title="Cerrar sesión"><LogOut size={17}/></button></div></div><button class="collapse-toggle" onclick={()=>ontoggle('collapse')} aria-label={collapsed?'Expandir menú':'Contraer menú'}>{#if collapsed}<ChevronRight size={17}/>{:else}<ChevronLeft size={17}/><span>Contraer menú</span>{/if}</button></aside>
